from pathlib import Path
import json,html,shutil
ROOT=Path(__file__).resolve().parents[3]
SOURCE=Path(__file__).parent
OUT=ROOT/'public/estudio-6e94b8f2c731/soluciones'
data=json.loads((OUT/'contenido.json').read_text());e=html.escape
for name in ['portal.css','portal.js']:shutil.copyfile(SOURCE/name,OUT/name)

def overview(post):
 return f'''<a href="#{post['id']}"><img src="{e(post['slides'][0]['file'])}" alt="Portada: {e(post['title'])}" width="1080" height="1080" loading="lazy"><small>{post['id']} · {e(post['sector'])}</small><h2>{e(post['title'])}</h2><span>Ver láminas y descripción →</span></a>'''

def section(post):
 id=post['id'];s=post['slides'][0];directory=f"archivos/{id}-{post['slug']}"
 return f'''<section class="post" id="{id}" aria-labelledby="{id}-title"><div class="post-head"><div><span class="meta">{id} · {e(post['sector'])}</span><h2 id="{id}-title">{e(post['title'])}</h2><p>{e(post['focus'])} · 5 JPG de 1080 × 1080 px</p></div><a class="button secondary" href="{directory}.zip" download>Descargar carrusel {id}</a></div><div class="post-grid"><div class="viewer" role="group" aria-roledescription="carrusel" aria-label="Láminas de {id}. Usa las flechas para recorrerlas." tabindex="0"><a class="slide-link" href="{e(s['file'])}" target="_blank" rel="noopener" aria-label="Abrir lámina 1 de {id} en tamaño completo"><img src="{e(s['file'])}" alt="{e(s['alt'])}" width="1080" height="1080" loading="lazy"></a><div class="viewer-controls"><button type="button" data-prev aria-label="Lámina anterior de {id}" disabled>←</button><span class="counter" data-counter aria-live="polite">Lámina 1 de 5</span><button type="button" data-next aria-label="Lámina siguiente de {id}">→</button></div><div class="slide-select" aria-label="Elegir lámina de {id}">{''.join(f'<button type="button" data-slide="{i}" aria-pressed="{str(i==0).lower()}" aria-label="Ver lámina {i+1} de {id}">{i+1}</button>' for i in range(5))}</div><div class="viewer-links"><a data-download-slide href="{e(s['file'])}" download="{id}-01-1080x1080.jpg">Descargar lámina 1</a><a href="archivos/Nexo-6-carruseles-vista-completa.pdf" target="_blank" rel="noopener">Ver colección en PDF</a></div></div><div class="copy-panel"><div class="copy-head"><h3>Descripción lista para copiar</h3></div><div class="network" aria-label="Elegir red para {id}"><button type="button" data-network="ig" aria-pressed="true">Instagram</button><button type="button" data-network="fb" aria-pressed="false">Facebook</button></div><label class="copy-label" for="{id}-caption">Descripción para Instagram</label><textarea class="caption" id="{id}-caption" readonly>{e(post['ig'])}</textarea><div class="copy-actions"><button class="button copy-button" type="button" data-copy-caption>Copiar descripción de Instagram</button><a data-caption-download href="{directory}/Descripcion-Instagram.txt" download>Descargar descripción TXT</a></div><p class="caption-hint">En Instagram, deja la web y WhatsApp en los enlaces del perfil. La descripción de Facebook ya incluye los enlaces.</p><details class="alt"><summary>Textos alternativos para las 5 láminas</summary><ol>{''.join('<li>'+e(slide['alt'])+'</li>' for slide in post['slides'])}</ol><a href="{directory}/Textos-alternativos.txt" download>Descargar textos alternativos</a></details></div></div></section>'''

page='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive,noimageindex"><meta name="referrer" content="no-referrer"><title>Nexo | Carruseles</title><link rel="icon" href="/favicon.ico" sizes="any"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="stylesheet" href="portal.css"></head><body><a href="#contenido" class="skip">Saltar al contenido</a><header class="site-header"><div class="wrap header-inner"><a href="../" aria-label="Volver al estudio de Nexo"><img class="logo" src="/brand/nexo-logo.svg" alt="Nexo" width="145" height="51"></a><nav aria-label="Navegación de la colección"><a href="#carruseles">Los 6 carruseles</a><a href="../">Estudio de contenido</a></nav></div></header><main class="wrap" id="contenido"><section class="hero"><p class="eyebrow">NEXO · COLECCIÓN 1:1</p><h1>Seis carruseles.<br>Listos para publicar.</h1><p class="intro">Seis rubros, seis problemas de trabajo y cómo conectarlos con un sistema a medida. Tienes las 30 láminas, sus descripciones y los archivos ordenados para Instagram y Facebook.</p><div class="actions"><a class="button" href="archivos/Nexo-6-carruseles-1a1.zip" download>Descargar los 6 carruseles</a><a class="button secondary" href="archivos/Nexo-6-carruseles-vista-completa.pdf" target="_blank" rel="noopener">Ver las 30 láminas en PDF</a></div><div class="quick-links"><a href="archivos/Descripciones-Instagram.txt" download>Descripciones de Instagram</a><a href="archivos/Descripciones-Facebook.txt" download>Descripciones de Facebook</a></div></section><nav class="overview" aria-label="Elegir un carrusel" id="carruseles">'''+''.join(overview(post) for post in data['posts'])+'''</nav><aside class="instructions" aria-labelledby="instructions-title"><h2 id="instructions-title">Cómo publicarlos</h2><p>Sube las cinco imágenes de cada carpeta en orden <strong>01–05</strong> y pega su descripción. Todas las láminas son cuadradas, de <strong>1080 × 1080 px</strong>. El PDF es para revisar; a Instagram subes los JPG.</p><p>Para tu prospección actual, comienza con <a href="#C01">C01 · Alquileres</a>. Los seis pueden publicarse como contenido orgánico. Las palabras ALQUILER, PEDIDOS y las demás ayudan a reconocer el tema de cada consulta; las respuestas se atienden manualmente.</p></aside>'''+''.join(section(post) for post in data['posts'])+'''<p class="source-note">Criterios de contenido y fuentes: <a href="https://github.com/julioroblesb/Demo-Sistema/blob/main/docs/contenido/criterio-seis-carruseles.md" target="_blank" rel="noopener">leer la base editorial</a>. <a href="archivos/COMO-PUBLICAR.txt" download>Descargar instrucciones</a>.</p></main><footer class="footer"><div class="wrap"><p>Nexo · Sistemas de información a medida · nexoamedida.com</p><p>Archivos preparados para publicar. No hay publicaciones programadas ni anuncios activados desde esta página.</p></div></footer><div class="status" id="status" role="status" aria-live="polite" hidden></div><script id="collection-data" type="application/json">'''+json.dumps(data['posts'],ensure_ascii=False).replace('<',r'\u003c')+'''</script><script src="portal.js" defer></script></body></html>'''
(OUT/'index.html').write_text(page)
